package com.bank.cert.model;

import java.math.BigDecimal;

public class Employee {
    private final String name;
    private final String department;
    private final int joinYear;
    private final BigDecimal salary;

    public Employee(String name, String department, int joinYear, BigDecimal salary) {
        this.name = name;
        this.department = department;
        this.joinYear = joinYear;
        this.salary = salary;
    }

    public String getName()       { return name; }
    public String getDepartment() { return department; }
    public int getJoinYear()      { return joinYear; }
    public BigDecimal getSalary() { return salary; }

    @Override public String toString() {
        return name + " (" + department + ", joined " + joinYear + ")";
    }
}
