package com.bank.cert.service;

import com.bank.cert.model.Employee;
import java.util.List;
import java.util.function.Predicate;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class EligibilityService {
    private static final Logger log = Logger.getLogger(EligibilityService.class.getName());

    public List<Employee> recentItStaff(List<Employee> employees) {
        // Two small, reusable, named predicates read like English.
        Predicate<Employee> isIt = e -> "IT".equals(e.getDepartment());
        Predicate<Employee> joinedAfter2015 = e -> e.getJoinYear() > 2015;

        log.info(() -> "Selecting IT staff who joined after 2015 from " + employees.size());
        return employees.stream()
                .filter(isIt.and(joinedAfter2015)) // combined AND predicate
                .collect(Collectors.toList());
    }
}
