    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT",    2018, new BigDecimal("95000")),
            new Employee("Vikram", "IT",    2010, new BigDecimal("88000")),
            new Employee("Priya",  "Sales", 2019, new BigDecimal("72000")),
            new Employee("Neha",   "IT",    2021, new BigDecimal("60000"))
        );

        EligibilityService service = new EligibilityService();
        service.recentItStaff(staff)
               .forEach(e -> log.info(() -> "Certificate recipient: " + e));
